    public function testPersistedSceneCanBeExplicitlyReviewedAfterRoleBindingChange(): void
    {
        $tenant=987654321;$user=987654322;$dir='uploads/micro-workbench-scene-tests/'.bin2hex(random_bytes(6));$root=dirname(__DIR__,2).'/public/';mkdir($root.$dir,0700,true);$png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/a9sAAAAASUVORK5CYII=');
        try{
            foreach(['a.png','b.png'] as $name){file_put_contents($root.$dir.'/'.$name,$png);Db::name('tenant_file')->insert(['tenant_id'=>$tenant,'source_id'=>$user,'source'=>1,'type'=>10,'cid'=>0,'uri'=>$dir.'/'.$name,'name'=>$name,'storage_scope'=>'platform','storage_engine'=>'local','storage_domain'=>'','create_time'=>time(),'delete_time'=>0]);}
            $before=Db::name('ai_consumption_log')->count();$project=$this->create('project',['script'=>['text'=>'用户确认的剧本','segments'=>[['duration'=>15]]],'roles'=>[['role_id'=>'lead','fixed_identity'=>true,'images'=>[['uri'=>$dir.'/a.png']]]],'scenes'=>[['scene_id'=>'s1','sort'=>1,'role_ids'=>['lead'],'mode'=>'reference','images'=>[],'confirmed'=>false]]],$tenant,$user);
            $save=static fn($r,$body)=>R::save($tenant,$user,['kind'=>'project','id'=>$r['id'],'revision'=>$r['revision'],'title'=>$r['title'],'body'=>$body]);
            $body=$project['body'];$body['scenes'][0]['confirmed']=true;$ready=$save($project,$body);self::assertSame('ready',$ready['body']['scenes'][0]['status']);
            $body=$ready['body'];$body['roles'][0]['images']=[['uri'=>$dir.'/b.png']];$stale=$save($ready,$body);self::assertFalse($stale['body']['scenes'][0]['confirmed']);self::assertSame('stale',$stale['body']['scenes'][0]['status']);
            $body=$stale['body'];$body['scenes'][0]['confirmed']=true;$reviewed=$save($stale,$body);self::assertSame('ready',$reviewed['body']['scenes'][0]['status']);self::assertNotEmpty($reviewed['body']['scenes'][0]['dependency_hash']);[$segments,$images]=W::executionReferences($reviewed['body']);self::assertSame($dir.'/b.png',$images[0]['uri']);
            $body=$reviewed['body'];$body['scenes'][0]['description']='修改后的画面';$body['scenes'][0]['confirmed']=true;$changed=$save($reviewed,$body);self::assertFalse($changed['body']['scenes'][0]['confirmed']);self::assertSame('stale',$changed['body']['scenes'][0]['status']);self::assertSame($before,Db::name('ai_consumption_log')->count());
        }finally{foreach(glob($root.$dir.'/*')?:[] as $path)unlink($path);rmdir($root.$dir);$parent=dirname($root.$dir);if(is_dir($parent)&&count(scandir($parent))===2)rmdir($parent);}
    }
    /** @dataProvider wholeRewriteSegmentCounts */
    public function testWholeRewriteClearsAssignmentsButHistoryRestoresTheirOwnedAssets(int $newCount): void
    {
        $tenant=987654321;$user=987654322;$dir='uploads/micro-workbench-rewrite-tests/'.bin2hex(random_bytes(6));$root=dirname(__DIR__,2).'/public/';mkdir($root.$dir,0700,true);$uri=$dir.'/kept.png';file_put_contents($root.$uri,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/a9sAAAAASUVORK5CYII='));
        try{
            $file=Db::name('tenant_file')->insertGetId(['tenant_id'=>$tenant,'source_id'=>$user,'source'=>1,'type'=>10,'cid'=>0,'uri'=>$uri,'name'=>'kept.png','storage_scope'=>'platform','storage_engine'=>'local','storage_domain'=>'','create_time'=>time(),'delete_time'=>0]);
            $before=Db::name('ai_consumption_log')->count();$body=['script'=>['text'=>'完整原剧本','segments'=>[['duration'=>15],['duration'=>15]]],'roles'=>[['role_id'=>'lead','images'=>[['uri'=>$uri]]]],'scenes'=>[['scene_id'=>'old1','sort'=>1,'role_ids'=>['lead'],'images'=>[['uri'=>$uri]],'mode'=>'scene'],['scene_id'=>'old2','sort'=>2,'role_ids'=>['lead'],'images'=>[['uri'=>$uri]],'mode'=>'scene']]];$project=$this->create('project',$body,$tenant,$user);
            $result=['script'=>['text'=>'完全替换的故事，段落含义已经改变。','continuity'=>'保留既有角色与商品事实','segments'=>array_fill(0,$newCount,['duration'=>$newCount===1?30:15])]];
            $job=J::table()->insertGetId(['tenant_id'=>$tenant,'user_id'=>$user,'project_id'=>$project['id'],'project_revision'=>1,'action'=>'rewrite','idempotency_key'=>'whole_rewrite_'.bin2hex(random_bytes(8)),'input_hash'=>str_repeat('e',64),'status'=>'success','request_json'=>'{}','receipt_json'=>'{}','result_json'=>json_encode($result),'create_time'=>time(),'update_time'=>time()]);
            $adopted=J::adopt($tenant,$user,['project_id'=>$project['id'],'project_revision'=>1,'job_id'=>$job]);self::assertSame([],$adopted['body']['scenes']);self::assertCount($newCount,$adopted['body']['script']['segments']);self::assertSame($uri,$adopted['body']['roles'][0]['images'][0]['uri']);self::assertSame(1,$adopted['body']['scene_reset']['previous_revision']);self::assertSame(2,$adopted['body']['scene_reset']['previous_scene_count']);
            $historical=R::versions($tenant,$user,['kind'=>'project','id'=>$project['id']])['lists'][1];self::assertCount(2,$historical['body']['scenes']);self::assertSame($uri,$historical['body']['scenes'][1]['images'][0]['uri']);self::assertSame(1,Db::name('tenant_file')->where('id',$file)->count());self::assertFileExists($root.$uri);
            $restored=R::restore($tenant,$user,['kind'=>'project','id'=>$project['id'],'revision'=>2,'version'=>1]);self::assertCount(2,$restored['body']['script']['segments']);self::assertCount(2,$restored['body']['scenes']);self::assertSame('完整原剧本',$restored['body']['script']['text']);self::assertFalse($restored['body']['scenes'][0]['confirmed']);self::assertSame('stale',$restored['body']['scenes'][0]['status']);self::assertFalse($restored['body']['script_stale']);
            $reviewed=$restored['body'];foreach($reviewed['scenes'] as &$scene)$scene['confirmed']=true;unset($scene);$ready=R::save($tenant,$user,['kind'=>'project','id'=>$project['id'],'revision'=>3,'title'=>$project['title'],'body'=>$reviewed]);[$segments,$images]=W::executionReferences($ready['body']);self::assertCount(2,$segments);self::assertSame($uri,$images[0]['uri']);self::assertSame($before,Db::name('ai_consumption_log')->count());
        }finally{unlink($root.$uri);rmdir($root.$dir);$parent=dirname($root.$dir);if(is_dir($parent)&&count(scandir($parent))===2)rmdir($parent);}
    }
    public static function wholeRewriteSegmentCounts(): array{return [[1],[2]];}
    /** @dataProvider historicalCatalogRevocation */
    public function testHistoricalRestoreKeepsTrustedCatalogSnapshotsAfterSourceRevocation(string $revocation): void
    {
        $before=Db::name('ai_consumption_log')->count();$template=R::save(1,0,['kind'=>'template','title'=>'Historical template','visibility'=>'tenant','body'=>['script'=>'template original','images'=>[]]],true);$product=R::save(1,0,['kind'=>'product','title'=>'Historical product','visibility'=>'tenant','body'=>['brand'=>'original brand','images'=>[]]],true);
        $project=$this->create('project',['template'=>['id'=>$template['id'],'revision'=>1],'product'=>['id'=>$product['id'],'revision'=>1],'script'=>['text'=>'与原始商品一致的剧本','segments'=>[]],'roles'=>[],'scenes'=>[]]);$body=$project['body'];$body['script_stale']=false;$body['stage']='script_ready';$coherent=R::save(1,1,['kind'=>'project','id'=>$project['id'],'revision'=>1,'title'=>'coherent original','body'=>$body]);
        $current=R::save(1,1,['kind'=>'project','id'=>$project['id'],'revision'=>2,'title'=>'new draft','body'=>['script'=>['text'=>'new unrelated script','segments'=>[]],'roles'=>[],'scenes'=>[]]]);
        foreach([$template,$product] as $source){if($revocation==='delete')R::delete(1,0,['kind'=>$source['kind'],'id'=>$source['id'],'revision'=>1],true);else R::save(1,0,['kind'=>$source['kind'],'id'=>$source['id'],'revision'=>1,'title'=>$source['title'],'visibility'=>'tenant','status'=>0,'body'=>$source['body']],true);}
        $restored=R::restore(1,1,['kind'=>'project','id'=>$project['id'],'revision'=>3,'version'=>2]);self::assertSame(4,$restored['revision']);self::assertSame('与原始商品一致的剧本',$restored['body']['script']['text']);self::assertSame('original brand',$restored['body']['product_snapshot']['body']['brand']);self::assertSame('template original',$restored['body']['template_snapshot']['body']['script']);self::assertSame(['id'=>$product['id'],'revision'=>1],$restored['body']['product']);self::assertFalse($restored['body']['script_stale']);self::assertSame('script_ready',$restored['body']['stage']);$copy=R::copy(1,1,['kind'=>'project','id'=>$project['id']]);self::assertSame(1,$copy['revision']);self::assertSame('original brand',$copy['body']['product_snapshot']['body']['brand']);self::assertNotSame($project['id'],$copy['id']);
        $this->rejects(fn()=>R::save(1,1,['kind'=>'project','title'=>'Forged history','body'=>['product'=>['id'=>$product['id'],'revision'=>1],'product_snapshot'=>$coherent['body']['product_snapshot']]]));self::assertSame($before,Db::name('ai_consumption_log')->count());
    }
    public static function historicalCatalogRevocation(): array{return [['delete'],['disable']];}
