    {$cross=array_column(W::capabilities(1)['cross_apps'],null,'app_code');self::assertArrayHasKey('aigc_image',$cross);self::assertArrayHasKey('aigc_product_image',$cross);self::assertSame(\app\common\service\app\AppAccessService::tenantCanUse(1,'aigc_image',false),$cross['aigc_image']['available']);self::assertSame(\app\common\service\app\AppAccessService::tenantCanUse(1,'aigc_product_image',false),$cross['aigc_product_image']['available']);}
    public function testTrustedHistoricalRestoreStillRequiresTheCurrentOwnedImageReceipt(): void
    {
        $tenant=987654321;$user=987654322;$dir='uploads/micro-workbench-history-image-tests/'.bin2hex(random_bytes(6));$root=dirname(__DIR__,2).'/public/';mkdir($root.$dir,0700,true);$uri=$dir.'/owned.png';file_put_contents($root.$uri,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/a9sAAAAASUVORK5CYII='));
        try{
            $file=Db::name('tenant_file')->insertGetId(['tenant_id'=>$tenant,'source_id'=>$user,'source'=>1,'type'=>10,'cid'=>0,'uri'=>$uri,'name'=>'owned.png','storage_scope'=>'platform','storage_engine'=>'local','storage_domain'=>'','create_time'=>time(),'delete_time'=>0]);$project=$this->create('project',['images'=>[['uri'=>$uri]]],$tenant,$user);R::save($tenant,$user,['kind'=>'project','id'=>$project['id'],'revision'=>1,'title'=>'new without image','body'=>['images'=>[]]]);Db::name('tenant_file')->where('id',$file)->update(['delete_time'=>time()]);
            $this->rejects(fn()=>R::restore($tenant,$user,['kind'=>'project','id'=>$project['id'],'revision'=>2,'version'=>1]));self::assertSame(2,(int)R::owned($tenant,$user,'project',$project['id'])['revision']);
        }finally{unlink($root.$uri);rmdir($root.$dir);$parent=dirname($root.$dir);if(is_dir($parent)&&count(scandir($parent))===2)rmdir($parent);}
    }
    public function testHttpFilteredRecordsAndHistoricalSnapshotsRemainTypedAfterSourceDeletion(): void
    {
        $template=R::save(1,0,['kind'=>'template','title'=>'Typed historical template','visibility'=>'tenant','body'=>['durations'=>[15,30],'roles'=>[['role_id'=>'template_lead','fixed_identity'=>true]],'images'=>[]]],true);
        $product=R::save(1,0,['kind'=>'product','title'=>'Typed historical product','visibility'=>'tenant','body'=>['facts'=>['duration'=>'0','confirmed'=>'0'],'images'=>[]]],true);
        $payload=['kind'=>'project','title'=>'HTTP type boundary','body'=>['template'=>['id'=>$template['id'],'revision'=>1],'product'=>['id'=>$product['id'],'revision'=>1],'script_stale'=>false,'target_duration'=>30,'brief'=>['target_duration'=>30,'requirements'=>'0'],'script'=>['text'=>'0','segments'=>[['sort'=>1,'duration'=>15,'image_indices'=>[0]]]],'roles'=>[['role_id'=>'lead','name'=>'0','fixed_identity'=>false]],'scenes'=>[]]];
        $filtered=(new \app\Request())->withPost($payload)->post();$project=R::save(1,1,$filtered);$stored=json_decode(R::owned(1,1,'project',$project['id'])['body_json'],true);self::assertSame([0],$stored['script']['segments'][0]['image_indices']);self::assertSame(15,$stored['script']['segments'][0]['duration']);self::assertFalse($stored['roles'][0]['fixed_identity']);self::assertTrue($stored['template_snapshot']['body']['roles'][0]['fixed_identity']);self::assertSame(['duration'=>'0','confirmed'=>'0'],$stored['product_snapshot']['body']['facts']);
        // Emulate a coherent pre-fix row/version whose HTTP trim filter persisted scalar strings.
        $body=$project['body'];$body['script_stale']=false;$body['stage']='script_ready';$legacy=(new \app\Request())->withPost(['body'=>$body])->post()['body'];$encoded=json_encode($legacy);R::table()->where('id',$project['id'])->update(['body_json'=>$encoded]);R::table('version')->where(['record_id'=>$project['id'],'revision'=>1])->update(['body_json'=>$encoded]);
        R::delete(1,0,['kind'=>'template','id'=>$template['id'],'revision'=>1],true);R::delete(1,0,['kind'=>'product','id'=>$product['id'],'revision'=>1],true);
        $dto=R::dto(R::owned(1,1,'project',$project['id']));self::assertFalse($dto['body']['script_stale']);self::assertSame(['id'=>$product['id'],'revision'=>1],$dto['body']['product']);$unchanged=(new \app\Request())->withPost(['kind'=>'project','id'=>$project['id'],'revision'=>1,'title'=>$project['title'],'body'=>$dto['body']])->post();$saved=R::save(1,1,$unchanged);self::assertFalse($saved['body']['script_stale']);self::assertSame('script_ready',$saved['body']['stage']);
        $restored=R::restore(1,1,['kind'=>'project','id'=>$project['id'],'revision'=>2,'version'=>1]);self::assertFalse($restored['body']['script_stale']);self::assertFalse($restored['body']['roles'][0]['fixed_identity']);self::assertTrue($restored['body']['template_snapshot']['body']['roles'][0]['fixed_identity']);self::assertSame([0],$restored['body']['script']['segments'][0]['image_indices']);self::assertSame(['duration'=>'0','confirmed'=>'0'],$restored['body']['product_snapshot']['body']['facts']);
    }
